 void layoutChrome(int width,int height){
  boolean landscape=width>height;if(landscape==landscapeLayout)return;landscapeLayout=landscape;
  toolbarStack.setOrientation(landscape?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);
  status.setSingleLine(landscape);status.setEllipsize(landscape?android.text.TextUtils.TruncateAt.END:null);status.setTextSize(landscape?10:12);status.setPadding(dp(9),dp(landscape?2:6),dp(9),dp(landscape?2:6));
  viewTools.setLayoutParams(new LinearLayout.LayoutParams(landscape?dp(340):-1,-2));
  mainTools.setLayoutParams(new LinearLayout.LayoutParams(landscape?dp(320):-1,-2));
  ((android.view.ViewGroup)bottomTools.getParent()).removeView(bottomTools);
  if(landscape)toolbarStack.addView(bottomTools,new LinearLayout.LayoutParams(dp(260),-2));
  else rootLayout.addView(bottomTools,new LinearLayout.LayoutParams(-1,-2));
 }
 void layoutFlyControls(){
  if(frame==null||flyTools==null)return;
  float density=getResources().getDisplayMetrics().density;
  NativeGaussianLayout.Plan plan=NativeGaussianLayout.plan(Math.round(frame.getWidth()/density),Math.round(frame.getHeight()/density));
  boolean active=renderer!=null&&renderer.pose().flyEye!=null;
  flyTools.setVisibility(active&&plan.visible?View.VISIBLE:View.GONE);
  if(!plan.visible)return;
  FrameLayout.LayoutParams outer=(FrameLayout.LayoutParams)flyTools.getLayoutParams();
  int wanted=dp(plan.width);if(outer.width!=wanted){outer.width=wanted;flyTools.setLayoutParams(outer);}
  int pad=dp(plan.height);boolean compact=plan.compact;
  if((flyLeans.getParent()==flyTools)!=compact){((android.view.ViewGroup)flyLeans.getParent()).removeView(flyLeans);if(compact)flyTools.addView(flyLeans);else flyLook.addView(flyLeans);}
  flyLeans.setOrientation(compact?LinearLayout.VERTICAL:LinearLayout.HORIZONTAL);
  setFlySize(movePad,0,pad,1);setFlySize(flyAxes,dp(58),pad,0);setFlySize(flyLook,0,pad,1);
  setFlySize(lookPad,-1,compact?pad:pad-dp(50),0);
  setFlySize(flyLeans,compact?dp(88):-1,compact?pad:dp(50),0);
  liftCaption.setVisibility(compact?View.GONE:View.VISIBLE);
  for(Button b:new Button[]{tiltLeft,tiltRight})setFlySize(b,compact?-1:0,dp(44),compact?0:1);
 }
 void setFlySize(View view,int width,int height,float weight){
  android.view.ViewGroup.LayoutParams existing=view.getLayoutParams();
  if(existing instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)existing;if(p.width==width&&p.height==height&&p.weight==weight)return;p.width=width;p.height=height;p.weight=weight;view.setLayoutParams(p);}
  else view.setLayoutParams(new LinearLayout.LayoutParams(width,height,weight));
 }
