 void range(LinearLayout c,String label,float value,float min,float max,java.util.function.Consumer<Float> setter){LinearLayout r=row();TextView caption=text(label,13);caption.setPadding(dp(3),dp(4),dp(3),dp(4));r.addView(caption,new LinearLayout.LayoutParams(0,-2,1));EditText input=numeric();input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);input.setText(String.format(Locale.ROOT,"%.3f",value));input.setTag(input.getText().toString());int numberWidth=dp(30)+(int)Math.ceil(input.getPaint().measureText("-360.000"));r.addView(input,new LinearLayout.LayoutParams(Math.max(dp(114),numberWidth),-2));SeekBar bar=new SeekBar(this);bar.setMax(1000);bar.setProgress(Math.round((value-min)/(max-min)*1000));c.addView(r);c.addView(bar,new LinearLayout.LayoutParams(-1,dp(40)));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){if(!user)return;float v=min+(max-min)*p/1000;input.setText(String.format(Locale.ROOT,"%.3f",v));input.setTag(input.getText().toString());setter.accept(v);surface.requestRender();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){saveState();}});input.setOnFocusChangeListener((v,focus)->{if(!focus&&!input.getText().toString().equals(input.getTag()))try{input.setError(null);float n=Float.parseFloat(input.getText().toString());if(!Float.isFinite(n)||n<min||n>max)throw new NumberFormatException();setter.accept(n);input.setTag(input.getText().toString());bar.setProgress(Math.round((n-min)/(max-min)*1000));surface.requestRender();saveState();}catch(Exception e){input.setError(word("数值超出范围","Value out of range"));}});input.setOnEditorActionListener((v,id,e)->{input.clearFocus();return true;});}
 void cameraDialog(){if(!renderer.ready)return;NativeGaussianRenderer.Camera cam=renderer.pose();LinearLayout c=column();range(c,word("水平角度","Azimuth"),cam.azimuth%360,-360,360,v->{synchronized(renderer){renderer.camera.azimuth=v;}});range(c,word("俯仰角度","Elevation"),cam.elevation,-90,90,v->{synchronized(renderer){renderer.camera.elevation=v;}});range(c,word("缩放","Zoom"),cam.flyEye==null||!cam.perspective?cam.zoom:cam.magnification,.05f,20,v->{synchronized(renderer){if(renderer.camera.flyEye==null||!renderer.camera.perspective)renderer.camera.zoom=v;else renderer.camera.magnification=v;}});range(c,word("漫游速度","Fly speed"),renderer.flySpeed,.01f,1,v->renderer.flySpeed=v);float[] currentEye=NativeGaussianRenderer.eye(cam);for(int a=0;a<3;a++){final int axis=a;LinearLayout position=row();position.addView(text(word("相机位置 ","Eye ")+"XYZ".charAt(a),12));EditText value=numeric();value.setSingleLine(true);value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);value.setText(String.format(Locale.ROOT,"%.6f",currentEye[a]+renderer.data.origin[a]));value.setTag(value.getText().toString());position.addView(value,new LinearLayout.LayoutParams(0,-2,1));value.setOnFocusChangeListener((v,focus)->{if(!focus&&!value.getText().toString().equals(value.getTag()))try{value.setError(null);double n=Double.parseDouble(value.getText().toString())-renderer.data.origin[axis];if(!Double.isFinite(n)||Math.abs(n)>1e9)throw new NumberFormatException();renderer.flying(true);synchronized(renderer){renderer.camera.flyEye[axis]=(float)n;}value.setTag(value.getText().toString());updateFly();surface.requestRender();saveState();}catch(Exception e){value.setError(word("无效位置","Invalid position"));}});c.addView(position);}Switch projection=new Switch(this);projection.setText(word("透视投影","Perspective"));projection.setChecked(cam.perspective);projection.setOnCheckedChangeListener((b,v)->renderer.projection(v));c.addView(projection);c.addView(text(word("旋转中心","Orbit pivot"),13));Spinner pivot=new Spinner(this);String[] modes={"view","fixed","model"};pivot.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{word("当前视野中心（自动）","View center (automatic)"),word("固定观察点","Fixed focus point"),word("模型中心","Model center")}));pivot.setSelection(Arrays.asList(modes).indexOf(renderer.orbitPivot));pivot.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,View view,int at,long id){renderer.orbitPivot=modes[at];saveState();}public void onNothingSelected(AdapterView<?> p){}});c.addView(pivot,new LinearLayout.LayoutParams(-1,dp(48)));Switch smooth=new Switch(this);smooth.setText(word("平滑相机移动","Smooth camera motion"));smooth.setChecked(renderer.smoothNavigation);smooth.setOnCheckedChangeListener((b,v)->renderer.smoothNavigation=v);c.addView(smooth);range(c,word("触摸灵敏度","Touch sensitivity"),renderer.rotateSpeed,.1f,3,v->renderer.rotateSpeed=v);range(c,word("摇杆转速 °/s","Look speed °/s"),renderer.lookSpeed,30,240,v->renderer.lookSpeed=v);range(c,word("倾斜角","Roll"),cam.roll,-180,180,v->{synchronized(renderer){renderer.camera.roll=v;}});LinearLayout actions=row();button(actions,"保存当前书签","Save view",()->{if(commitFocused(c))saveBookmark();});button(actions,"恢复适应","Fit",()->{commitFocused(c);if(cameraWindow!=null)cameraWindow.dismiss();renderer.fit();surface.requestRender();updateFly();});c.addView(actions);ScrollView scroll=new ScrollView(this);scroll.addView(c);cameraWindow=new AlertDialog.Builder(this).setTitle(word("相机微调","Camera")).setView(scroll).setPositiveButton(word("完成","Done"),null).create();cameraWindow.setOnShowListener(d->cameraWindow.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(commitFocused(c)){saveState();cameraWindow.dismiss();}}));cameraWindow.show();}
 void displayDialog(){if(!renderer.ready)return;LinearLayout c=column();c.addView(text(word("保留全部高斯；拖动时降低画面分辨率与球谐阶数，停止后恢复。截图使用完整画质。","All splats retained. Motion lowers image resolution/SH degree; idle restores quality. Capture uses full quality."),13));range(c,word("交互分辨率比例","Motion resolution"),renderer.motionScale,.35f,1,v->renderer.motionScale=v);range(c,word("静止分辨率比例","Idle resolution"),renderer.idleScale,.5f,1.5f,v->renderer.idleScale=v);ScrollView scroll=new ScrollView(this);scroll.addView(c);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(word("显示","Display")).setView(scroll).setPositiveButton(word("完成","Done"),null).create();displayWindow=dialog;dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(commitFocused(c)){saveState();dialog.dismiss();}}));dialog.show();}
 void saveBookmark(){if(!renderer.ready)return;if(bookmarks.length()>=100){Toast.makeText(this,word("最多 100 个书签","At most 100 views"),Toast.LENGTH_SHORT).show();return;}EditText name=new EditText(this);name.setSingleLine(true);name.setText(word("视角 ","View ")+(bookmarks.length()+1));new AlertDialog.Builder(this).setTitle(word("保存当前视角","Save current view")).setView(name).setPositiveButton(word("保存","Save"),(d,w)->{try{String n=name.getText().toString().trim();if(n.isEmpty()||n.length()>120)throw new IOException("Invalid name");bookmarks.put(new JSONObject().put("name",n).put("camera",NativeGaussianCamera.encode(renderer.pose(),renderer.data.origin)));saveState();}catch(Exception e){error(e.getMessage());}}).setNegativeButton(word("取消","Cancel"),null).show();}
 void bookmarksDialog(){LinearLayout c=column();LinearLayout actions=row();button(actions,"保存当前","Save",this::saveBookmark);button(actions,"导入","Import",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json"),IMPORT_BOOKMARKS));button(actions,"导出","Export",this::exportBookmarks);c.addView(actions);for(int i=0;i<bookmarks.length();i++){final int index=i;JSONObject b=bookmarks.optJSONObject(i);LinearLayout r=row();Button load=button(r,b.optString("name"),b.optString("name"),()->{if(renderer.ready)try{synchronized(renderer){renderer.camera=NativeGaussianCamera.decode(b.getJSONObject("camera"),renderer.data.origin);}renderer.movement(0,0,0);surface.requestRender();updateFly();saveState();}catch(Exception e){error(e.getMessage());}});button(r,"删除","Delete",()->{JSONArray next=new JSONArray();for(int j=0;j<bookmarks.length();j++)if(j!=index)next.put(bookmarks.opt(j));bookmarks=next;saveState();r.setVisibility(View.GONE);});c.addView(r);}if(bookmarks.length()==0)c.addView(text(word("书签保存在此项目中，下次打开自动保留。支持 JSON 导入导出。","Views persist in this project and can be imported/exported as JSON."),13));ScrollView scroll=new ScrollView(this);scroll.addView(c);new AlertDialog.Builder(this).setTitle(word("视角书签","Saved views")).setView(scroll).setPositiveButton(word("关闭","Close"),null).show();}
 void exportBookmarks(){try{JSONObject file=new JSONObject().put("schema",1).put("kind","bwv-native-gaussian-bookmarks").put("bookmarks",bookmarks);File dest=new File(getCacheDir(),"native-gaussian-bookmarks.json");try(OutputStream out=new FileOutputStream(dest)){out.write(file.toString(2).getBytes("UTF-8"));}screenshotFile=dest;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"BuildingWebViewer-Gaussian-Views.json"),SAVE_BOOKMARKS);}catch(Exception e){error(e.getMessage());}}
 void saveState(){if(store==null||closed)return;try{JSONObject state=new JSONObject().put("schema",1).put("selected",new JSONArray(selected.toString())).put("bookmarks",new JSONArray(bookmarks.toString())).put("motionScale",renderer.motionScale).put("idleScale",renderer.idleScale).put("flySpeed",renderer.flySpeed).put("orbitPivot",renderer.orbitPivot).put("smoothNavigation",renderer.smoothNavigation).put("rotateSpeed",renderer.rotateSpeed).put("controlsVersion",2).put("lookSpeed",renderer.lookSpeed);if(renderer.ready&&renderer.data!=null){savedCamera=NativeGaussianCamera.encode(renderer.pose(),renderer.data.origin);state.put("camera",savedCamera);}else if(savedCamera!=null)state.put("camera",savedCamera);io.execute(()->{try{store.saveState(projectId,"gaussian-native",state);}catch(Exception e){main.post(()->{if(!closed)status.setText(word("保存失败：","Save failed: ")+e.getMessage());});}});}catch(Exception e){error(e.getMessage());}}
 @Override public void stage(String phase){main.post(()->{if(closed)return;loadingCard.setVisibility(View.VISIBLE);progress.setIndeterminate(true);loadingText.setText(word(phase.equals("upload")?"上传完整属性到显卡…":phase.equals("sort")?"准备首次深度排序…":phase.equals("warmup")?"预热渲染与截图画质…":"正在生成完整画质截图…",phase.equals("upload")?"Uploading full attributes to GPU…":phase.equals("sort")?"Preparing first depth order…":phase.equals("warmup")?"Warming render quality…":"Capturing at full quality…"));});}
 static List<File> authorizedFiles(ProjectStore store,String id,JSONArray keys)throws Exception{if(keys.length()==0||keys.length()>64)throw new IOException("Choose 1 to 64 Gaussian files");JSONArray records=store.get(id).getJSONArray("files");Map<String,String> allowed=new HashMap<>();for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);allowed.put(r.getString("key"),r.getString("path"));}List<File> files=new ArrayList<>();for(int i=0;i<keys.length();i++){String key=keys.getString(i);if(!allowed.containsKey(key)||!allowed.get(key).toLowerCase(Locale.ROOT).endsWith(".ply"))throw new IOException("Gaussian file is not in this project");File f=store.objectFile(key);if(!f.isFile())throw new IOException("Project file is missing");files.add(f);}return files;}
 boolean touch(MotionEvent e){int action=e.getActionMasked(),n=e.getPointerCount();if(action==MotionEvent.ACTION_DOWN)orbitStarted=false;if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL||action==MotionEvent.ACTION_POINTER_UP){fingers=0;orbitStarted=false;main.removeCallbacks(restoreQuality);main.postDelayed(restoreQuality,470);return true;}float x=e.getX(),y=e.getY(),span=0;if(n>=2){x=(e.getX(0)+e.getX(1))/2;y=(e.getY(0)+e.getY(1))/2;span=(float)Math.hypot(e.getX(0)-e.getX(1),e.getY(0)-e.getY(1));}if(action==MotionEvent.ACTION_MOVE&&fingers==n){if(n==1&&!orbitStarted){renderer.beginOrbit();orbitStarted=true;}renderer.gesture(x-lastX,y-lastY,n>=2&&lastSpan>2&&span>2?span/lastSpan:1,n>=2);}fingers=n;lastX=x;lastY=y;lastSpan=span;main.removeCallbacks(restoreQuality);return true;}
 @Override public void ready(int count){main.post(()->{if(closed)return;loading=false;loadingCard.setVisibility(View.GONE);capture.setEnabled(true);diagnose.setEnabled(true);if(!restoredCamera&&savedCamera!=null)try{synchronized(renderer){renderer.camera=NativeGaussianCamera.decode(savedCamera,renderer.data.origin);}surface.requestRender();}catch(Exception ignored){}restoredCamera=true;updateFly();saveState();status.setText(java.text.NumberFormat.getIntegerInstance().format(count)+word(" 个高斯 · "," splats · ")+selected.length()+word(" 个文件"," files"));});}
 @Override public void error(String message){main.post(()->{if(closed)return;loading=false;loadingCard.setVisibility(View.GONE);capture.setEnabled(false);status.setText(word("加载失败：","Load failed: ")+message);});}
 @Override public void screenshot(Bitmap bitmap){io.execute(()->{try{File dir=new File(getCacheDir(),"exports/native-gaussian-"+UUID.randomUUID());if(!dir.mkdirs())throw new IOException("Cannot create screenshot folder");File file=new File(dir,"BuildingWebViewer-Gaussian.png");try(OutputStream out=new FileOutputStream(file)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("Cannot encode image");}finally{bitmap.recycle();}if(closed)return;screenshotFile=file;main.post(()->{if(closed)return;loadingCard.setVisibility(View.GONE);capture.setEnabled(true);Intent pick=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/png").putExtra(Intent.EXTRA_TITLE,"BuildingWebViewer-Gaussian.png");startActivityForResult(pick,SAVE_IMAGE);});}catch(Exception e){error(e.getMessage());}});}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==IMPORT_BOOKMARKS){if(result==RESULT_OK&&intent!=null&&intent.getData()!=null){Uri chosen=intent.getData();io.execute(()->{try(InputStream in=getContentResolver().openInputStream(chosen)){JSONArray incoming=NativeGaussianCamera.importBookmarks(new JSONObject(BoundedIO.readLimited(in,1024*1024)));main.post(()->{if(closed)return;try{if(bookmarks.length()+incoming.length()>100)throw new IOException("At most 100 bookmarks");for(int i=0;i<incoming.length();i++)bookmarks.put(incoming.get(i));saveState();Toast.makeText(this,word("书签已导入","Views imported"),Toast.LENGTH_SHORT).show();}catch(Exception e){error(e.getMessage());}});}catch(Exception e){error(e.getMessage());}});}return;}if(request!=SAVE_IMAGE&&request!=SAVE_BOOKMARKS)return;File file=screenshotFile;screenshotFile=null;if(result!=RESULT_OK||intent==null||file==null)return;Uri uri=intent.getData();if(uri==null)return;io.execute(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Cannot open image destination");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);main.post(()->{if(!closed)Toast.makeText(this,word("截图已保存","Image saved"),Toast.LENGTH_SHORT).show();});}catch(Exception e){error(e.getMessage());}});}
 void diagnostics(){String[] actions={word("自动旋转采集 10 秒","Automatic orbit sample (10 seconds)"),word("手动拖动采集 10 秒","Manual sample (10 seconds)"),word("查看报告","View report")};new AlertDialog.Builder(this).setTitle(word("原生渲染诊断","Native rendering diagnostics")).setItems(actions,(dialog,index)->{if(index<2){capture.setEnabled(false);diagnose.setEnabled(false);renderer.sample(index==0);main.postDelayed(()->{if(!closed)renderer.endSample();},10000);Toast.makeText(this,word("正在采集 10 秒","Sampling for 10 seconds"),Toast.LENGTH_SHORT).show();}else showReport();}).setNegativeButton(word("关闭","Close"),null).show();}
 @Override public void sampled(JSONObject report){try{report.put("loading",report.getJSONObject("loading").put("cpuParseMs",parseMs).put("memoryCacheHit",cacheHit));}catch(Exception ignored){}lastReport=report;getSharedPreferences("native-gaussian",MODE_PRIVATE).edit().putString("lastReport",report.toString()).apply();main.post(()->{if(!closed){capture.setEnabled(renderer.ready);diagnose.setEnabled(true);Toast.makeText(this,word("诊断完成，可复制报告","Sample complete; report can be copied"),Toast.LENGTH_SHORT).show();}});}
 void showReport(){String text;try{JSONObject r=lastReport!=null?lastReport:new JSONObject(getSharedPreferences("native-gaussian",MODE_PRIVATE).getString("lastReport","{}"));text=r.toString(2);}catch(Exception e){text="{}";}final String report=text;TextView view=new TextView(this);view.setTextIsSelectable(true);view.setText(report);view.setTextSize(12);view.setPadding(dp(12),dp(12),dp(12),dp(12));ScrollView scroll=new ScrollView(this);scroll.addView(view);new AlertDialog.Builder(this).setTitle(word("原生渲染报告","Native rendering report")).setView(scroll).setPositiveButton(word("复制","Copy"),(d,w)->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("BuildingWebViewer native diagnostics",report));}).setNegativeButton(word("关闭","Close"),null).show();}
 @Override protected void onResume(){super.onResume();if(surface!=null){surface.onResume();surface.requestRender();}}
 @Override protected void onPause(){if(movePad!=null)movePad.reset();resetLookButtons();if(renderer!=null)renderer.pause();saveState();if(surface!=null)surface.onPause();super.onPause();}
 @Override protected void onDestroy(){closed=true;if(loadTask!=null)loadTask.cancel(true);main.removeCallbacksAndMessages(null);if(renderer!=null)renderer.destroy();io.shutdown();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);super.onDestroy();}
